import os
import tomllib
from typing import Any


class ConfigError(Exception):
    def __init__(self, key: str, expected: str):
        self.key = key
        self.expected = expected
        super().__init__(f"Config error: key '{key}' expected type {expected}")


def _deep_merge(base: dict, override: dict) -> dict:
    result = dict(base)
    for k, v in override.items():
        if k in result and isinstance(result[k], dict) and isinstance(v, dict):
            result[k] = _deep_merge(result[k], v)
        else:
            result[k] = v
    return result


def _coerce_int(s: str) -> int:
    try:
        return int(s)
    except ValueError:
        raise ConfigError(s, "int")


def _coerce_float(s: str) -> float:
    try:
        return float(s)
    except ValueError:
        raise ConfigError(s, "float")


def _coerce_bool(s: str) -> bool:
    lower = s.lower()
    if lower in ("true", "yes", "1"):
        return True
    if lower in ("false", "no", "0"):
        return False
    raise ConfigError(s, "bool")


def _coerce_str(s: str) -> str:
    if not s:
        raise ConfigError(s, "str")
    return s


def _env_key(prefix: str, path: list[str]) -> str:
    return "__".join((prefix.upper(), *(p.upper() for p in path)))


