    assert envcfg._coerce_int("42") == 42
    assert envcfg._coerce_int("-7") == -7


def test_coerce_int_invalid():
    with pytest.raises(envcfg.ConfigError):
        envcfg._coerce_int("abc")


def test_coerce_float_valid():
    assert envcfg._coerce_float("3.14") == 3.14
    assert envcfg._coerce_float(".5") == 0.5
    assert envcfg._coerce_float("1e3") == 1000.0


